@module gridPane  src=gridPane.lua  loc=1162  mode=chunk  self=gridPane
@deps cm, cmgr, chrome, gui, tv, inputAllowed, chordEntry

# Invariants & contracts
  @invariant  grid render + input only; tracker state lives in tv/ec, never cached here  @ 4
  @invariant  col.x == nil is the visibility predicate; per-column draws must gate on it  @ 5
  @invariant  cell coords 0-indexed; header rows at -HEADER, row-num gutter at -GUTTER  @ 6
  @invariant  page-persistent state: cellW/H, dragging, laneConsumed, paintLast  @ 7
  @contract  host supplies inputAllowed() -- folds modal/picker/item-active/palette/strip gates  @ 8
  @contract  host chordEntry=false gates the chord gesture off (the pattern editor passes false)  @ 9
  @contract  bails if laneConsumed; lane strip wins gestures over the tracker grid  @ 959
  @contract  right-click on channel-label row toggles mute  @ 960
  @contract  click on label rows selects channel/column  @ 961
  @contract  body click moves cursor and arms drag  @ 962
  @contract  no-op unless inputAllowed(); host folds modal/picker/item-active/palette/strip  @ 1102
  @contract  every fresh press enters; only lastEditKey autorepeats  @ 1103
  @contract  scans editKeys per frame; reads ec/grid fresh (editEvent may rebuild)  @ 1104
  @contract  a note key typed while armed exits region mode then enters (execute-through)  @ 1105
  @contract  Shift+notechar strikes chords (+Alt spreads channels); Shift+digit value place-walk  @ 1106
  @contract  Backspace deletes last chord note; Shift+=/- nudges vel; shift release commits  @ 1107

# Imports
  @require util = 'util'  @ 10
  @require groups = 'groups'  @ 11
  @require ImGui = 'imgui'  @ 17
  @require painter = 'painter'  @ 18

# Constructed sub-instances
  @construct curveEditor = util.instantiate('curveEditor')  @ 59

