  @state HEADER = 3  @ 26   -- header rows, fixed; vertical param names truncate to fit, never grow it
  @state RESERVE_ROWS = 0.3  @ 27   -- bottom breathing left clear below the last row (status band / modal edge)
  @state ANCHOR_HALO = 6  @ 28   -- px; matches curveEditor HIT_PX so the hit-rect covers anchors on the rect edge
