  @state chanLeft, chanWidth, totalWidth = {}, {}, 0  @ 38
  @state ctx, gridFont, uiFont = gui.ctx, gui.font, gui.uiFont  @ 57
  @state dragging = false  @ 58   -- tracker-grid selection drag: click → held → release
  @state laneConsumed = false  @ 60
  @state paintLast = nil  @ 62   -- region-paint per-cell debounce
  @state renderFns = {  @ 176
  @state READOUT_SIZE = 11  @ 199
  @state VNAME_MAX = 14  @ 290
  @state laneRenderable = { cc = true, pb = true, at = true }  @ 363
      @invariant  lane strip renders only cc/pb/at; other types show as tinted background  @ 362
  @state LANE_ROW_MIN = 3  @ 365
  @state LANE_ROW_MAX = 32  @ 366
  @state PART_LABEL = { pitch = 'PITCH', sample = 'SAMP', vel = 'VEL', delay = ...  @ 495
      @contract  assumes computeLayout ran this frame; reads chanLeft/Width/Order, gridOriginX/Y  @ 492
  @state NO_OVERLAY = { notes = {}, values = {}, hidden = {} }  @ 511   -- caret outside every chain: no ghosts, nothing suppressed
  @state editKeys = {}  @ 851
  @state lastEditKey  @ 869
  @state gridPane = {}  @ 873

# Private functions
  @fn layoutColumns(cols, scrollCol)  @ 41-55
      @contract  clears col.x on every col before assigning; off-screen cols stay nil  @ 40
  -- Cell renderers
  @fn renderNote(evt, col, row)  @ 66-148
  @fn renderPB(evt)  @ 150-155
  @fn renderCC(evt, col)  @ 157-164
  @fn renderFx(_, col, row)  @ 168-174
      -- The region's chain, one stage per row from the badge down, resolved off the registry as the
      -- view minted the stack; live stages keep the cell's default colour, bypassed ones dim like the fx tab.
  @fn renderCell(evt, col, row)  @ 186-189
  @fn delayMarkerOffset(col, pitchWidth)  @ 193-195
      -- Offset of the gap before the 3 delay digits in a note cell (* marker slot).
      -- Layout: pitch(W, active pitchWidth) + optional readout(1) + optional sample(3) + ' ' + vel(2).
  -- Drawing
  @fn printer(x0, y0)  @ 205-270
      -- Cell adapter over the shared painter: col/row → screen via one transform.
      -- cellW/cellH are odd integers (whole-pixel landing); snap handles fractional cases.
  @fn laneStripRows()  @ 273-276
      @contract  returns 0 when laneStrip.visible is false; layout and draw branch on this  @ 272
  @fn drawLocalScrim(draw, hole, w, h)  @ 280-286
      -- Local-mode wash: dim the whole grid except a hole at the instance the caret sits
      -- inside (`hole`, grid units); nil hole washes everything. Overlays the cell pass.
  @fn vnameSize()  @ 292
  @fn vnameGap()  @ 296
      -- Bottom gap under a vertical name, in rows: clear of the grid's top rule
      -- with a couple of px of breathing room.
  @fn vname(label)  @ 300-325
      -- Rotated param name, trimmed to fit the fixed header. Binary search finds
      -- the longest prefix whose rotated strip fits, exact under variable-width fonts.
  @fn ensureCellSize()  @ 329-337
      -- cellW/cellH: odd px so 1px strokes land on pixel centres. Lazy: first layout or measure.
      -- Measure under the grid font: naturalWidth() may trigger this before draw's font push.
  @fn computeLayout(budgetW, budgetH)  @ 342-358
      -- RESERVE_ROWS of breathing is kept clear at the bottom for every caller; the grid fills the rest.
      @contract  must run before draws reading chanLeft/chanWidth/totalWidth/viewRows  @ 339
      @contract  calls tv:setGridSize so tv scroll math sees the live viewport  @ 340
  -- Lane strip
  @fn curveEditorFrame(col, colIdx, rect, tMin, tMax, hovered)  @ 370-415
      -- Build the curve-editor FrameArgs for `col` over row-space [tMin,tMax] in `rect`; returns
      -- true iff it consumed the mouse. Shared by the lane strip and the pattern editor's curve pane.
  @fn drawLaneStrip()  @ 419-490
      @contract  publishes laneConsumed=true if curve editor claimed input this frame  @ 417
      @contract  handleMouse short-circuits on laneConsumed  @ 418
  @fn notePartHeaders(col)  @ 497-509
  @fn drawTracker()  @ 513-819
  -- Input
  @fn cellAt(mouseX, mouseY)  @ 825-828
      -- Screen point -> (fractional column, integer row) through the grid painter's
      -- inverse, so a click resolves against the exact transform the draw pass used.
  @fn nearestStop(mouseX, mouseY)  @ 832-847
      @contract  returns (col, stop, fracX) or (nil, nil, fracX)  @ 830
      @invariant  fracX is separate so callers distinguish 'past last col' from 'inside col N'  @ 831
  @fn add(key, byte, digit)  @ 853

# Public API (gridPane:*)
  @api gridPane:draw(gridW, gridH)  @ 878-885
      -- Draw pass: computeLayout twice (lane-drag callbacks may rebuild grid.cols,
      -- so drawTracker needs a fresh layout), with the grid font pushed throughout.
      @invariant  lane-strip drag callbacks may flush tv.grid.cols and clear col.x  @ 877
  @api gridPane:geom()  @ 888-890
      -- Grid geometry for the host's help:anchor (which spans grid + palette).
  @api gridPane:naturalWidth()  @ 894-899
      -- Intrinsic pixel width of the current grid (gutter + every column). Lets the pattern
      -- editor size the grid to its exact content and hand the rest of the width to the curve.
  @api gridPane:heightForRows(rows)  @ 903-906
      -- Content-region pixel height for `rows` grid rows (header, lane strip, bottom breathing);
      -- inverts computeLayout. +2px cancels its RESERVE subtraction so pixel rounding can't clip the last row.
  @api gridPane:cellHeight()  @ 908
  @api gridPane:cellWidth()  @ 909
  @api gridPane:drawCurveEditor(rect)  @ 914-957
      -- time -> X across the grid's scrolled window, so scrolling pans/zooms the curve and a
      -- fitting pattern shows whole; assumes gridPane:draw ran first this frame (reads viewRows).
      @contract  renders the current column's curve into `rect`; sets laneConsumed  @ 911
  @api gridPane:handleMouse()  @ 963-1098
  @api gridPane:handleKeys(kr)  @ 1108-1160
      -- commandHeld gates note entry per key: a key bound to both a command and note
      -- entry (e.g. '.' = delete) fires the command; unrelated keys still enter.

